use crate::app::{App, ParamStore};

pub const CHANNELS: usize = 1;

pub static CONFIG: Config<2> = Config::new("Test Clean", "A clean POC submission", Color::Blue, AppIcon::Fader)
    .add_param(Param::Color { name: "Color", variants: &[Color::Blue, Color::Green] })
    .add_param(Param::bool { name: "Invert" });

pub async fn wrapper(app: App<CHANNELS>, params: ParamStore<Params>) {
    select(run(&app), params.param_handler()).await;
}

pub async fn run(app: &App<CHANNELS>) {
    loop {
        app.use_buttons().wait_for_down(0).await;
    }
}

